// Build-time localization support for preproc.
//
// Translation tables are generated by tools/localization/loc.py, one per
// source file, at <table dir>/<source path>.tbl. Each line is one of:
//
//   C <line> <fnv1a64 of original bytes> <replacement hex bytes | ->
//   S <line> <fnv1a64 of original bytes> <replacement hex bytes | ->
//
// 'C' entries replace a C string (_(), __(), COMPOUND_STRING()) whose
// converted bytes hash to the given value; when several share a hash the one
// with the closest line wins. 'S' entries replace the asm '.string' directive
// on exactly that line ('-' means the directive emits nothing because its
// text was merged into the first line of the unit).
//
// The graphics overlay redirects INCGFX/INCBIN paths to localized copies.
// WARNING: LocalizedGraphicsPath must stay in-sync with 'tools/scaninc'.

#ifndef LOCALIZATION_H
#define LOCALIZATION_H

#include <cstdint>
#include <map>
#include <string>
#include <vector>

class LocTables
{
public:
    LocTables(std::string tableDir, std::string usageLog);

    // Returns true and fills 'out' if a C string should be replaced.
    bool LookupC(const std::string& file, long line, const std::vector<unsigned char>& original, std::vector<unsigned char>& out);

    // Returns true and fills 'out' if an asm .string line should be replaced.
    // 'error' is set (and true returned) if the entry is stale.
    bool LookupAsm(const std::string& file, long line, const unsigned char* original, int length, std::vector<unsigned char>& out, std::string& error);

private:
    struct Entry
    {
        long line;
        std::uint64_t hash;
        bool drop;
        std::vector<unsigned char> bytes;
    };

    struct Table
    {
        std::multimap<std::uint64_t, Entry> cEntries;
        std::map<long, Entry> asmEntries;
    };

    std::string m_tableDir;
    std::string m_usageLog;
    std::map<std::string, Table> m_tables;

    Table& GetTable(const std::string& file);
    void LogUsage(const std::string& file, long line);
};

extern LocTables* g_locTables;

std::uint64_t Fnv1a64(const unsigned char* data, std::size_t length);
std::string NormalizeSourcePath(const std::string& path);

// Returns 'path' redirected into 'overlayDir' if a localized version exists,
// otherwise returns 'path' unchanged. For INCGFX the source image itself is
// looked up. For INCBIN (isIncbin) the built file's source image is looked
// up by replacing everything after the first '.' of the file name with
// '.png' or '.pal'.
std::string LocalizedGraphicsPath(const std::string& overlayDir, const std::string& path, bool isIncbin);

#endif // LOCALIZATION_H
